// One row per website: skips empty and inactive rows and removes duplicates (each check costs credits).
// The previous severity and score come from the same row, so the next step can tell what changed.
const out = [];
const seen = new Set();
for (const item of $input.all()) {
  const r = item.json;
  const website = String(r.website || '').trim();
  if (!website || String(r.active || '').trim().toLowerCase() === 'no') continue;
  const domain = website.toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[\/?#]/)[0].replace(/\.$/, '');
  if (seen.has(domain)) continue;
  seen.add(domain);
  const score = String(r.health_score ?? '').trim();
  out.push({ json: {
    website, domain,
    client: String(r.client || '').trim() || domain,
    client_email: String(r.client_email || '').trim(),
    previous_severity: String(r.severity || '').trim().toLowerCase(),
    previous_score: score === '' || isNaN(Number(score)) ? null : Number(score),
  } });
}
return out;

// Turns the two Weio answers for one site into a health score, plain-English issues and a change flag.
// https-check: {ok, results: [{host, visible, cause, plain, expired_days, not_after}]} for the bare address and www.
// site-info: {ok, reachable, error, final_url, http_status, title, description, mobile_viewport, role_emails, phones,
// contact_page, credits_remaining}. 401/402 = key or credits; 400 = not a website address (not charged);
// 429/5xx = busy (not charged, retried next run).
const s = $('Settings').first().json;
const site = $('Loop over sites').item.json;
const parse = r => {
  let b = r && r.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = { error: b.slice(0, 200) }; } }
  return { code: Number(r && r.statusCode) || 0, body: b && typeof b === 'object' ? b : {} };
};
const https = parse($('Check HTTPS').item.json);
const info = parse($json);
let api = 'ok';
for (const r of [https, info]) {
  if (r.code === 401 || r.code === 402) api = 'key';
  else if (api === 'ok' && r.code === 400) api = 'invalid';
  else if (api === 'ok' && r.code !== 200) api = 'retry';
}
const issues = [];
const add = (sev, text) => issues.push({ sev, text });
let cert_expires = '';
const f = info.body;
if (api === 'ok') {
  const results = Array.isArray(https.body.results) ? https.body.results : [];
  const bare = results.find(a => !String(a.host).startsWith('www.')) || {};
  cert_expires = bare.not_after || '';
  for (const a of results) {
    const days = typeof a.expired_days === 'number' ? -a.expired_days : null;
    if (a.visible === 'unknown') {
      // a missing www. record is common and harmless; only an unreachable bare domain counts
      if (!String(a.host).startsWith('www.')) add('critical', `${a.host} cannot be reached: the domain or server is gone.`);
    } else if (a.visible === 'interstitial') {
      add('critical', `${a.host}: browsers block it with a full-page warning (${String(a.cause || 'certificate problem').replace(/_/g, ' ')}).`);
    } else if (a.visible === 'not_secure') {
      add('warning', `${a.host}: shows "Not secure" because http does not redirect to https.`);
    } else if (days !== null && days <= s.critical_days) {
      add('critical', `${a.host}: the certificate expires in ${days} day(s), on ${a.not_after}.`);
    } else if (days !== null && days <= s.warn_days) {
      add('warning', `${a.host}: the certificate expires in ${days} days, on ${a.not_after}.`);
    }
  }
  // site-info reads politely: a robots.txt refusal is the owner's choice, not an outage, so it is only noted.
  const st = Number(f.http_status) || 0;
  // A bare address that is gone or blocked by a certificate warning already explains a page that did not load.
  const bareBroken = results.some(a => !String(a.host).startsWith('www.') && (a.visible === 'unknown' || a.visible === 'interstitial'));
  if (/^robots/.test(String(f.error || ''))) {
    if (!bareBroken) add('info', f.error === 'robots disallow'
      ? 'The site does not allow automated reading (robots.txt), so the home-page checks were skipped.'
      : 'The home page could not be read (its robots.txt did not load), so the home-page checks were skipped.');
  } else if (st >= 500) {
    add('critical', `The home page returns a server error (HTTP ${st}).`);
  } else if (st >= 400) {
    add('warning', `The home page returns HTTP ${st}.`);
  } else if (f.reachable === false && !bareBroken) {
    add('critical', 'The home page did not load: no answer from the server.');
  }
  if (f.reachable === true) {
    if (f.mobile_viewport === false) add('warning', 'No mobile layout tag: phones probably show a shrunken desktop page.');
    if (!f.title) add('warning', 'The home page has no title, so search results and browser tabs show the bare address.');
    if (!f.description) add('info', 'No meta description: Google writes its own snippet for search results.');
    if (!((f.role_emails || []).length || (f.phones || []).length || f.contact_page)) {
      add('info', 'No email address, phone number or contact page found on the home page.');
    }
    try {
      const host = new URL(f.final_url).hostname.replace(/^www\./, '');
      if (host && host !== site.domain) add('info', `The address now redirects to ${host}.`);
    } catch (e) {}
  }
}
const count = sev => issues.filter(i => i.sev === sev).length;
let severity = count('critical') ? 'critical' : count('warning') ? 'warning' : 'ok';
let score = Math.max(0, 100 - 40 * count('critical') - 15 * count('warning') - 5 * count('info'));
if (api === 'invalid') {
  severity = 'invalid'; score = '';
  add('warning', 'Not a valid website address: fix this row (nothing was charged).');
} else if (api === 'retry') {
  severity = 'retry'; score = '';
  add('info', 'The check service was busy: this site is checked again next run (nothing was charged).');
}
const rank = { ok: 0, warning: 1, critical: 2 };
const prev = site.previous_severity;
let change = 'same';
if (severity in rank) {
  if (!(prev in rank)) change = 'new';
  else if (rank[severity] > rank[prev]) change = 'worse';
  else if (rank[severity] < rank[prev]) change = severity === 'ok' ? 'resolved' : 'better';
  else if (site.previous_score !== null && score <= site.previous_score - 10) change = 'worse';
}
const credits = [f.credits_remaining, https.body.credits_remaining].find(c => typeof c === 'number');
return { json: {
  website: site.website, client: site.client, client_email: site.client_email,
  severity, health_score: score, change,
  issues: issues.map(i => `[${i.sev}] ${i.text}`).join('\n'),
  cert_expires,
  mobile_ready: api !== 'ok' || f.reachable !== true ? '' : f.mobile_viewport === true ? 'yes' : f.mobile_viewport === false ? 'no' : '',
  contact_found: api !== 'ok' || f.reachable !== true ? '' : ((f.role_emails || []).length || (f.phones || []).length || f.contact_page) ? 'yes' : 'no',
  checked_at: new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC',
  api_status: api,
  api_error: api === 'key' ? String(([https, info].find(r => r.code === 401 || r.code === 402) || {}).body.error || 'API key problem') : '',
  credits_remaining: credits === undefined ? null : credits,
} };

// One Gmail draft per client with the sites that need work, in plain English. Nothing is sent: the drafts wait
// in your Gmail for review. Sites without a client_email are skipped; 'info' notes stay internal.
const s = $('Settings').first().json;
if (!s.client_report_drafts) return [];
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const groups = {};
for (const r of $input.all().map(i => i.json)) {
  if (!(r.severity === 'critical' || r.severity === 'warning') || !r.client_email) continue;
  (groups[r.client_email] = groups[r.client_email] || []).push(r);
}
return Object.entries(groups).map(([email, sites]) => {
  const items = sites.map(r => {
    const lines = String(r.issues).split('\n').filter(l => !l.startsWith('[info]')).map(l => l.replace(/^\[\w+\] /, ''));
    return `<p><b>${esc(r.website)}</b> (health score ${esc(r.health_score)}/100)</p><ul>` +
      lines.map(l => `<li>${esc(l)}</li>`).join('') + '</ul>';
  }).join('');
  const n = sites.length;
  return { json: {
    client_email: email, client: sites[0].client,
    subject: `${sites[0].client}: ${n === 1 ? 'one website item' : n + ' website items'} to look at this week`,
    html: `<p>Hi,</p><p>Our weekly check of your website found something worth fixing:</p>${items}` +
      `<p>Reply to this email and we will take care of it.</p><p>${esc(s.agency_name)}</p>`,
  } };
});

// One weekly report for your team: new or worse sites first, then the rest still open, what got fixed,
// rows to repair and the credits left on your Weio key.
const BUY = 'https://weio.ai/services/site-check-api.html?utm_source=n8n&utm_medium=templates&utm_campaign=site-health';
const s = $('Settings').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.website);
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sev = r => r.severity === 'critical' ? 0 : 1;
const open = rows.filter(r => r.severity === 'critical' || r.severity === 'warning')
  .sort((a, b) => sev(a) - sev(b) || Number(a.health_score) - Number(b.health_score));
const worse = open.filter(r => r.change === 'new' || r.change === 'worse');
const still = open.filter(r => !worse.includes(r));
const fixed = rows.filter(r => r.change === 'resolved' || r.change === 'better');
const retry = rows.filter(r => r.severity === 'retry');
const invalid = rows.filter(r => r.severity === 'invalid');
// credits_left travels with each history row (after a loop, $('Score website health') only holds the last site)
const left = rows.map(r => r.credits_left).filter(c => c !== '' && c !== null && c !== undefined && !isNaN(Number(c))).map(Number);
const credits = left.length ? Math.min(...left) : null;
const li = r => `<li><b>${esc(r.website)}</b> (${esc(r.client)}): ${r.severity}, ${esc(r.health_score)}/100` +
  `<br><small>${esc(r.issues).replace(/\n/g, '<br>')}</small></li>`;
const n = k => rows.filter(r => r.severity === k).length;
let html = `<p>Checked ${rows.length} website(s): ${n('critical')} critical, ${n('warning')} warning, ${n('ok')} healthy.</p>`;
if (worse.length) html += `<h3>New or worse this week</h3><ul>${worse.map(li).join('')}</ul>`;
if (still.length) html += `<h3>Still open</h3><ul>${still.map(li).join('')}</ul>`;
if (fixed.length) html += `<h3>Fixed or better</h3><ul>${fixed.map(r => `<li>${esc(r.website)}: now ${r.severity}</li>`).join('')}</ul>`;
if (retry.length) html += `<p>${retry.length} site(s) are checked again next run (the service was busy; not charged).</p>`;
if (invalid.length) html += `<p>Rows without a valid website address: ${invalid.map(r => esc(r.website)).join(', ')}.</p>`;
if (credits !== null) html += `<p>Credits left on your Weio key: ${credits}` +
  (credits < s.low_credit_warning ? ` (running low, <a href="${BUY}">top up</a>)` : '') + '.</p>';
return [{ json: {
  email_to: s.team_email,
  subject: `Website health: ${worse.length} new or worse, ${open.length} open, ${fixed.length} fixed`,
  html, counts: { checked: rows.length, critical: n('critical'), warning: n('warning'), ok: n('ok'), worse: worse.length, fixed: fixed.length },
} }];
